        let otherwiseInputs = Inputs.vectors(H.self, seed: 0xCDCC_718B_46A6_4FC2)
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0xCDCC_728B_46A6_5175)
        let fromInputs = Inputs.buffers(Lane.self, count: H.laneCount, seed: 0xCDCC_6F8B_46A6_4C5C)
        let indicesInputs = Inputs.tableIndices(
            SIMD<Int32>.self,
            count: H.laneCount,
            seed: 0xCDCC_708B_46A6_4E0F,
            inContract: true
        )
        for (otherwise, mask, from, indices) in mixedQuadruples(
            otherwiseInputs,
            maskInputs,
            fromInputs,
            indicesInputs,
            seed: 0xF21C_5085_303D_EA06
        ) {
            let indices = poisoned(indices, where: mask, with: H.laneCount)
            let (portResult, referenceResult) = from.withUnsafeBufferPointer { source in
                (
                    { () -> SIMD<Float> in
                        var indices = indices
                        var mask = mask
                        var otherwise = otherwise
                        return withUnsafeTemporaryAllocation(of: SIMD<Float>.self, capacity: 1) {
                            result in
                            unsafe portGatherWhereOtherwiseF32InVectorCode(
                                result.baseAddress.unsafelyUnwrapped,
                                from: source.baseAddress!,
                                indices: &indices,
                                where: &mask,
                                otherwise: &otherwise
                            )
                            return unsafe result.baseAddress.unsafelyUnwrapped.move()
                        }
                    }(),
                    { () -> SIMD<Float> in
                        var indices = indices
                        var mask = mask
                        var otherwise = otherwise
                        return withUnsafeTemporaryAllocation(of: SIMD<Float>.self, capacity: 1) {
                            result in
                            unsafe highwayGatherWhereOtherwiseF32InVectorCode(
                                result.baseAddress.unsafelyUnwrapped,
                                from: source.baseAddress!,
                                indices: &indices,
                                where: &mask,
                                otherwise: &otherwise
                            )
                            return unsafe result.baseAddress.unsafelyUnwrapped.move()
                        }
                    }()
                )
            }
            mismatches.check(
