    @Test func scatter() {
        let mismatches = Mismatches("portScatterF32InVectorCode")
        let aInputs = Inputs.vectors(H.self, seed: 0x74A1_AC93_2335_BF82)
        let indicesInputs = Inputs.tableIndices(
            SIMD<Int32>.self,
            count: H.laneCount,
            seed: 0x74A1_AD93_2335_C135,
            inContract: true
        )
        let sentinel = Inputs.sentinel(Lane.self, count: H.laneCount + 4)
        for (a, indices) in everyPair(aInputs, indicesInputs) {
            var portLanes = sentinel
            portLanes.withUnsafeMutableBufferPointer { destination in
                { () -> Void in
                    var a = a
                    var indices = indices
                    unsafe portScatterF32InVectorCode(
                        &a,
                        to: destination.baseAddress!,
                        indices: &indices
                    )
                }()
            }
            var referenceLanes = sentinel
            referenceLanes.withUnsafeMutableBufferPointer { destination in
                { () -> Void in
                    var a = a
                    var indices = indices
                    unsafe highwayScatterF32InVectorCode(
                        &a,
                        to: destination.baseAddress!,
                        indices: &indices
                    )
                }()
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), indices: \(describe(indices))"
            )
        }
        mismatches.record()
    }

